import{c as r,Q as e,j as a,m as s}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Your Agent Harness Should Repair Itself","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-08-@akshay_pachaar-498924.md","filePath":"research/tweets/2026-06-08-@akshay_pachaar-498924.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-06-08-@akshay_pachaar-498924.md"};function n(i,t,l,d,h,g){return e(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="your-agent-harness-should-repair-itself" tabindex="-1">Your Agent Harness Should Repair Itself <a class="header-anchor" href="#your-agent-harness-should-repair-itself" aria-label="Permalink to &quot;Your Agent Harness Should Repair Itself&quot;">​</a></h1><p><strong>作者</strong>：Akshay 🚀 (@akshay_pachaar)<br><strong>發布時間</strong>：2026-06-08<br><strong>原始連結</strong>：<a href="https://x.com/akshay_pachaar/status/2064051835636498924" target="_blank" rel="noreferrer">https://x.com/akshay_pachaar/status/2064051835636498924</a><br><strong>類型</strong>：Twitter Article（贊助文 — Comet ML / Opik）<br><strong>統計</strong>：1107 likes · 148 retweets · 2508 bookmarks · 580215 views</p><hr><h2 id="分析摘要" tabindex="-1">分析摘要 <a class="header-anchor" href="#分析摘要" aria-label="Permalink to &quot;分析摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Opik（Comet ML）贊助文，提出 Harness 自我修復 4 層閉環：bad trace → Ollie AI 診斷 → diff 提案 → 批准 → rerun 驗證 → regression 鎖定。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>觀測性平台盲區</strong>：現有工具只回答「what happened」，不回答「why / what to fix / won&#39;t break again」</li><li><strong>Ollie</strong>：Opik 內建 coding agent，讀取 span tree + 源代碼 → 提具體 diff → 用戶批准後重跑驗證 → 失敗鎖入 regression suite</li><li><strong>4 層架構</strong>：Tracing（@opik.track decorator）→ Ollie → Test Suites（plain-English assertions）→ Agent Sandbox（端到端 UI 測試）</li><li><strong>Flywheel</strong>：每次生產失敗自動成為新 test case；harness 每輪更難打破</li><li><strong>Regression-first 測試</strong>：測試從真實失敗生長，非預先設計合成場景</li></ol><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>明確贊助文</strong>（&quot;Thanks to Comet ML for sponsoring today&#39;s issue&quot;）——客觀性受限</li><li>Ollie 的 diff 提案 + 用戶批准 flow 是好設計原則，但 Opik 特定</li><li>觀測性缺口框架（what/why/fix/prevent 四層）有普世分析價值</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>理由</th></tr></thead><tbody><tr><td>A. Workspace 可行動性</td><td>4/10</td><td>Opik 特定，無法直接套用 cc-workspace</td></tr><tr><td>B. 創新性</td><td>6/10</td><td>trace→fix→regression 閉環 framing 新穎</td></tr><tr><td>C. 證據品質</td><td>3/10</td><td>贊助文，19.3K GitHub stars 是唯一量化數據</td></tr><tr><td>D. 技術深度</td><td>5/10</td><td>4 層架構有細節，但全圍繞 Opik</td></tr><tr><td>E. 泛化性</td><td>6/10</td><td>觀測性 4 層框架普世適用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>4.65/10</strong></td><td></td></tr></tbody></table><p><strong>整合決策</strong>：不整合（&lt; 6 分，贊助文，Opik 特定）<br><strong>整合狀態</strong>：inbox/low-score</p><hr><h2 id="全文摘要" tabindex="-1">全文摘要 <a class="header-anchor" href="#全文摘要" aria-label="Permalink to &quot;全文摘要&quot;">​</a></h2><p>When an AI agent fails in production, your observability tool shows you exactly what it did and almost nothing about how to fix it.</p><p>The real bottleneck isn&#39;t your observability. It&#39;s everything that has to happen after the trace lands on your screen.</p><p><strong>The four-layer stack:</strong></p><ol><li><strong>Tracing</strong>: <code>@opik.track</code> decorator, works with LangGraph, CrewAI, 50+ frameworks</li><li><strong>Ollie</strong>: coding agent that reads span trees + source → proposes diff → user approves → reruns agent → locks regression test</li><li><strong>Test Suites</strong>: plain-English assertions converted to LLM-as-a-judge checks; grows from real production failures</li><li><strong>Agent Sandbox</strong>: run fully instrumented agent end-to-end in UI; non-developer stakeholders can test safely</li></ol><p><strong>The loop</strong>: Instrument → something fails → Ollie reads trace + source → proposes fix → approve → rerun in Sandbox → lock as regression test → repeat.</p><p>Every cycle, the harness gets harder to break.</p><p><em>Sponsored by Comet ML. 19.3K GitHub stars. Self-hosts in 3 commands.</em></p>',22)])])}const u=r(o,[["render",n]]);export{c as __pageData,u as default};
